function toJSLiteral(val, indent = 0) {
  const pad = '  '.repeat(indent);
  const pad1 = '  '.repeat(indent + 1);

  if (val === null) return 'null';
  if (val === undefined) return 'undefined';

  if (typeof val === 'boolean') return val.toString();
  if (typeof val === 'number') return val.toString();

  if (typeof val === 'string') {
    // Check if multiline
    if (val.includes('\n')) {
      // Escape backticks and dollar-brace for template literals
      const escaped = val.replace(/\\\\/g, '\\\\\\\\').replace(/\`/g, '\\\\\`').replace(/\\$\\{/g, '\\\\$\\{');
      return '\`' + escaped + '\`';
    } else {
      // Single-line: use JSON.stringify (produces double-quoted string)
      return JSON.stringify(val);
    }
  }

  if (Array.isArray(val)) {
    if (val.length === 0) return '[]';
    const items = val.map(v => pad1 + toJSLiteral(v, indent + 1));
    return '[\\n' + items.join(',\\n') + '\\n' + pad + ']';
  }

  if (typeof val === 'object') {
    const keys = Object.keys(val);
    if (keys.length === 0) return '{}';
    const entries = keys.map(k => {
      const safeKey = /^[a-zA-Z_\$][a-zA-Z0-9_\$]*\$/.test(k) ? k : JSON.stringify(k);
      return pad1 + safeKey + ': ' + toJSLiteral(val[k], indent + 1);
    });
    return '{\\n' + entries.join(',\\n') + '\\n' + pad + '}';
  }

  return String(val);
}

