const fs = require('fs');
const json = JSON.parse(fs.readFileSync('tutors.json', 'utf8'));
const topics = require('./topics-4-7.js');

function deepEqual(a, b, path) {
  if (path === undefined) path = 'root';
  if (a === b) return true;
  if (typeof a !== typeof b) {
    console.log('Type mismatch at', path, ':', typeof a, 'vs', typeof b);
    return false;
  }
  if (a === null || b === null) {
    if (a !== b) {
      console.log('Null mismatch at', path);
      return false;
    }
    return true;
  }
  if (typeof a === 'string') {
    if (a !== b) {
      // Find first difference
      for (var i = 0; i < Math.max(a.length, b.length); i++) {
        if (a[i] !== b[i]) {
          console.log('String mismatch at', path, 'position', i, ':',
            JSON.stringify(a.substring(Math.max(0, i-10), i+20)),
            'vs',
            JSON.stringify(b.substring(Math.max(0, i-10), i+20))
          );
          break;
        }
      }
      return false;
    }
    return true;
  }
  if (typeof a !== 'object') return a === b;
  if (Array.isArray(a)) {
    if (!Array.isArray(b)) {
      console.log('Array vs non-array at', path);
      return false;
    }
    if (a.length !== b.length) {
      console.log('Array length mismatch at', path, ':', a.length, 'vs', b.length);
      return false;
    }
    for (var i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i], path + '[' + i + ']')) return false;
    }
    return true;
  }
  var keysA = Object.keys(a);
  var keysB = Object.keys(b);
  if (keysA.length !== keysB.length) {
    console.log('Key count mismatch at', path, ':', keysA.length, 'vs', keysB.length);
    return false;
  }
  for (var k of keysA) {
    if (!b.hasOwnProperty(k)) {
      console.log('Missing key', k, 'at', path);
      return false;
    }
    if (!deepEqual(a[k], b[k], path + '.' + k)) return false;
  }
  return true;
}

var allMatch = true;
for (var i = 0; i < 4; i++) {
  var jsonTopic = json.los[i + 3];
  var jsTopic = topics[i];
  var match = deepEqual(jsonTopic, jsTopic, 'topic' + (i + 4));
  console.log('Topic', i + 4, '(' + jsonTopic.id + '):', match ? 'MATCH' : 'MISMATCH');
  if (!match) allMatch = false;
}
console.log('\\nAll topics match:', allMatch);
"
